  "finland_notes_v1": "[{\"id\": \"note_mock_1\", \"title\": \"2026 Commercial Rate Card & Value Pricing Strategy\", \"content\": \"\\u2022 Daily Studio Rate: \\u20ac1,200 / day\\n\\u2022 Weekly Creative Sprint: \\u20ac5,000 / week\\n\\u2022 Dedicated Project Retainer: \\u20ac4,500 / month (covers up to 40 hours)\\n\\u2022 Value add-on: 3D interactive physics and shader engineering billed at premium tier.\\n\\u2022 Never discount without removing explicit deliverables.\", \"isPinned\": true, \"color\": \"#f59e0b\", \"labelId\": \"lbl_strategy\", \"label\": \"Value Pricing & Strategy\", \"dueDate\": \"2026-11-14\", \"updatedAt\": \"2026-11-09\"}, {\"id\": \"note_mock_2\", \"title\": \"Client Discovery & Technical Scoping Framework\", \"content\": \"1. Send async intake questionnaire (business goals, visual inspirations, hard deadlines).\\n2. 45-min Zoom discovery alignment meeting.\\n3. Draft detailed Scope of Work with explicit out-of-scope boundaries.\\n4. Issue 50% advance invoice before scheduling kickoff.\\n5. Establish shared Slack/Discord channel with automated notifications.\", \"isPinned\": true, \"color\": \"#10b981\", \"labelId\": \"lbl_ops\", \"label\": \"Studio Operations\", \"dueDate\": \"2026-11-18\", \"updatedAt\": \"2026-11-06\"}, {\"id\": \"note_mock_3\", \"title\": \"WebGL & Shader Interactive Physics Architecture\", \"content\": \"Architecture notes for custom Three.js / WebGPU liquid physics simulations:\\n- Run simulation compute passes on GPU via ping-pong framebuffer textures.\\n- Offload UI interactions to Web Workers to ensure steady 120 FPS on ProMotion screens.\\n- Mobile fallback: procedural 2D canvas particle emitter with subtle gyroscope parallax.\\n- Memory target: keep total VRAM allocation under 45MB.\", \"isPinned\": false, \"color\": \"#8b5cf6\", \"labelId\": \"lbl_concepts\", \"label\": \"Creative Direction & Concepts\", \"dueDate\": \"2026-11-21\", \"updatedAt\": \"2026-11-04\"}, {\"id\": \"note_mock_4\", \"title\": \"Studio Sora Brand System & Motion Language Rules\", \"content\": \"Key motion principles for the Studio Sora launch:\\n- Spring physics: mass 1.0, stiffness 280, damping 24 for all drawer and modal transitions.\\n- Micro-interactions: 120ms cubic-bezier(0.16, 1, 0.3, 1) ease-out.\\n- Dark mode tokens: slate-950 base with 1px border highlight (white/10).\\n- Sound design: 20ms subtle tactile click on primary CTA tap.\", \"isPinned\": false, \"color\": \"#3b82f6\", \"labelId\": \"lbl_client\", \"label\": \"Client Work\", \"dueDate\": \"2026-11-10\", \"updatedAt\": \"2026-11-02\"}, {\"id\": \"note_mock_5\", \"title\": \"Kinetic AI Multi-Platform Type Specimen & Font Pairing\", \"content\": \"Typography system approved for Q1 web and product interfaces:\\n- Primary Display: Plus Jakarta Sans Bold / Extrabold (tight letter-spacing -0.03em).\\n- Body Text: Inter / IBM Plex Sans for ultra-crisp cross-platform legibility.\\n- Code / Telemetry: JetBrains Mono for data readouts and financial ledger tables.\\n- Optical sizing: dynamic CSS font-variation-settings for headers above 32px.\", \"isPinned\": false, \"color\": \"#ec4899\", \"labelId\": \"lbl_design\", \"label\": \"Design Systems & Type\", \"dueDate\": \"2026-11-25\", \"updatedAt\": \"2026-10-30\"}, {\"id\": \"note_mock_6\", \"title\": \"Quarterly SaaS Audit: Consolidating Fragmented Tool Subscriptions\", \"content\": \"Replaced Monday.com, Harvest, QuickBooks, and Notion with this bespoke Finland ledger.\\n\\u2022 Immediate direct savings: ~\\u20ac180 / month in duplicate SaaS licenses.\\n\\u2022 Cash flow visibility: instant tri-currency conversion ($ \\u2022 \\u20ac \\u2022 \\u20aa) in one offline-first vault.\\n\\u2022 Next step: migrate project archives from cloud storage to local encrypted drives.\", \"isPinned\": false, \"color\": \"#10b981\", \"labelId\": \"lbl_ops\", \"label\": \"Studio Operations\", \"dueDate\": \"2026-11-29\", \"updatedAt\": \"2026-10-27\"}, {\"id\": \"note_mock_7\", \"title\": \"Asset Handover & Production Archive Checklist\", \"content\": \"Standard delivery package for final milestone sign-off:\\n1. Clean vector asset exports (SVG, PDF, optimized WebP).\\n2. Figma tokens published to client workspace with viewer permissions.\\n3. Source code git repository tagged with v1.0.0 release.\\n4. Written handoff documentation and 14-day warranty support period.\", \"isPinned\": false, \"color\": \"#3b82f6\", \"labelId\": \"lbl_client\", \"label\": \"Client Work\", \"dueDate\": \"2026-12-02\", \"updatedAt\": \"2026-10-24\"}, {\"id\": \"note_mock_8\", \"title\": \"Tax Deductions, Workspace & Studio Hardware Depreciation\", \"content\": \"Eligible studio write-offs for current tax year:\\n- All software subscriptions, domains & hosting infrastructure.\\n- High-performance studio monitors & MacBook Pro workstation (3-year linear depreciation).\\n- High-speed fiber internet and mobile data (85% business allocation).\\n- Design reference library, type foundry licenses, and educational conferences.\", \"isPinned\": false, \"color\": \"#f59e0b\", \"labelId\": \"lbl_strategy\", \"label\": \"Value Pricing & Strategy\", \"dueDate\": \"2026-11-07\", \"updatedAt\": \"2026-10-20\"}]",
